        originalName: "Soul Shred",
        actionType: "passive",
        description: "Criaturas mortas por um governador falso são difíceis de trazer de volta à vida ou animar como mortos-vivos. O governador falso tenta automaticamente contrapôr qualquer tentativa de ressuscitar ou animar como morto-vivo qualquer criatura que tenha matado (modificador de contrapôr +36, círculo 7). Se o governador falso que matou a criatura for morto, a criatura pode ser trazida de volta da morte ou tornar-se morta-viva normalmente.",
