        originalName: "Manifest Body",
        actionType: "passive",
        frequency: "1 vez por dia",
        description: "O governador falso manifestou um corpo humanoide oco ao redor da estrutura esquelética esguia que parece idêntico ao do Governador Heh Shan-Bao. Enquanto usa esse corpo manifestado, o governador falso perde o Golpe de garra, e a voz soa como a de Heh Shan-Bao. O corpo manifestado do governador falso deteriora-se depressa se ele não gastar 10 minutos 1 vez por dia para manter a manifestação da carne falsa. O corpo tem 10 PV e as mesmas defesas do governador falso. Quando o corpo é destruído, o governador falso emerge ileso, e a casca carnosa deixada para trás se dispersa numa nuvem de borboletas vermelhas que logo se dissolvem em névoa vermelha. Essa emergência é tão macabra e perturbadora que todas as criaturas a até 9 m que a testemunharem devem tentar uma salvaguarda de Fortitude CD 29 ou ficam Enjoadas 2 (Enjoadas 3 em falha crítica); isto tem os traços mental e visual.",
