        description: "Quando um guhdggi empunha uma arma quebrada não mágica, não sofre nenhuma das desvantagens da arma estar quebrada. Enquanto o guhdggi a empunha, a arma se torna uma arma +1 striking que causa 1d6 de dano mental adicional num acerto.",
