        name: "Então Você Ouviu?",
        originalName: "So Have You Heard?",
        actionType: "passive",
        frequency: "1 vez por dia",
        description: "A Vovó Hu pode alterar a reputação de um PC em Willowshore ao longo de 2 horas de trabalho. Ela tenta um teste de Enganação contra a CD de Enganação, Diplomacia ou Intimidação do alvo, a que for mais alta. Se o alvo for admirado ou reverenciado por pelo menos uma facção em Willowshore, a Vovó Hu sofre –1 de penalidade de status no teste, ou –2 se o alvo for admirado ou reverenciado pelas duas facções. O alvo fica então imune temporariamente a Então Você Ouviu? por 1 semana.\n\nSucesso crítico O alvo sofre –2 de penalidade de circunstância em testes de perícia baseados em Carisma ao interagir com residentes de Willowshore por uma semana.\nSucesso Como sucesso crítico, mas apenas –1 de penalidade de circunstância e por apenas 1 dia.\nFalha O alvo não é afetado.\nFalha crítica O plano sai pela culatra; além de o alvo não ser afetado, a Vovó Hu não pode usar Então Você Ouviu? por 1 mês.",
