        description: "A imprecasia lança Purificar Aflição contra uma maldição que aflige uma criatura. Se for bem-sucedida em remover a maldição, também inala vitalidade da criatura (parecendo sugar fios azuis de vapor do corpo do alvo), fazendo a criatura ficar Drenada 1 a menos que passe numa salvaguarda de Fortitude CD 30 (Drenada 2 em falha crítica). Se a maldição for removida, a imprecasia não gasta aquele uso de Purificar Aflição como magia inata primal.\n\nAlvejar Itens\nUma imprecasia pode lançar Remover Maldição num item amaldiçoado em vez de numa criatura, mas não pode usar Devorar Maldição nele. Só pode fazê-lo num item de nível igual ou inferior ao próprio nível; em sucesso, o item deixa de estar amaldiçoado por 24 horas se for de nível igual ou superior ao nível da imprecasia –4, ou deixa de estar amaldiçoado permanentemente se for de nível inferior a isso.",
