        originalName: "Sagebane",
        actionType: "passive",
        description: "Quando o monge de Kugaptee causa dano a uma criatura viva com um Golpe de punho ou uma arma com o traço monge, o alvo deve passar numa salvaguarda de Fortitude CD 24 ou fica Estupefato 1 por 1 minuto.\nDano adicional causado pelo monge de Kugaptee reinicia a duração para 1 minuto e aumenta o valor de Estupefato em 1 numa salvaguarda falha, até o máximo de Estupefato 4.",
