        originalName: "Scarlet Apoxia",
        actionType: "passive",
        description: "O alvo não pode recuperar-se da condição Fatigado causada pela apoxia escarlate até a doença ser curada.\nSalvaguarda de Fortitude CD 24\nEstágio 1 portador sem efeito nocivo (1 dia)\nEstágio 2 Drenado 1 e Fatigado (1 dia)\nEstágio 3 Drenado 2 e Fatigado (1 dia)\nEstágio 4 morto (uma criatura que morra de apoxia escarlate reencarna como um nindoru de nível igual ou inferior 24 horas após a morte, a menos que o corpo receba um funeral adequado; uma vez ocorrida a reencarnação, a criatura morta não pode ser restaurada à vida original até o nindoru no qual reencarnou ser primeiro morto)",
