        description: "Criaturas mortas por um sojiruh são difíceis de trazer de volta à vida ou animar como mortos-vivos. O sojiruh tenta automaticamente contrapôr qualquer tentativa de ressuscitar ou animar qualquer criatura que tenha matado (modificador de contrapôr +11, círculo 2). Se o sojiruh que matou a criatura for ele próprio morto, a criatura pode ser trazida de volta da morte ou tornar-se morta-viva normalmente.",
