        name: "Empunhador de Ruína",
        originalName: "Ruin Wielder",
        actionType: "passive",
        description: "Quando um sojiruh empunha uma arma quebrada não mágica, não sofre nenhuma das desvantagens da arma estar quebrada. Enquanto o sojiruh a empunha, a arma se torna uma arma +1 que causa 1d6 de dano mental adicional num acerto.",
