        description: "A condição do vaso de uma aranha de pedra dita os PV máximos. Intacta, o vaso é um objeto com 62 PV (limiar de quebra 31). Quando a aranha de pedra está em forma espiritual, danificá-la não fere o vaso, mas danificar o vaso causa a mesma quantidade de dano à aranha de pedra. Quando a aranha de pedra Habita o Vaso, são um único alvo, e o dano reduz os PV tanto da aranha de pedra quanto do vaso. Se o vaso estiver quebrado, a aranha de pedra ainda pode lutar enquanto o habita e não sofre efeito adverso, mas se o vaso for alguma vez destruído, a aranha de pedra é morta instantaneamente e não pode reconstituir-se.",
