        description: "O waldgeist de Willowshore faz milhares de folhas de papel voarem das ruínas da Casa do Papel das Nuvens para cortar a carne. Todas as criaturas numa explosão de 6 m a até 27 m do waldgeist de Willowshore sofrem 8d6 de dano cortante (salvaguarda básica de Reflexos CD 24). Uma criatura que falhe criticamente nesta salvaguarda fica parcialmente soterrada em montes de folhas de papel e Atrasada 1 por 1 rodada.",
